"""第一段階を基準に、生成JSONと厳密走査の第二段階を同じruntimeでbuildする。"""
import pathlib,json,subprocess,shutil,os,hashlib,time
p=pathlib.Path(__file__).resolve().parent;root=p.parents[1];old=root/'var/posting-json-20261025'
# 通常試験が通るまでは性能用imageを採用しない。
while not (p/'validation-normal.json').exists():
 if (p/'validation-progress-retry.log').exists() and 'Traceback' in (p/'validation-progress-retry.log').read_text():raise RuntimeError('normal checks failed')
 time.sleep(2)
previous=json.loads((old/'setup.json').read_text())
for f,h in previous['source_sha256'].items():assert hashlib.sha256((old/'candidate-source'/f).read_bytes()).hexdigest()==h,f
changed=subprocess.check_output(['git','ls-files','-m','-o','--exclude-standard'],cwd=root,text=True).splitlines();changed=sorted({f for f in changed if f.endswith('.go') and f.startswith(('internal/','cmd/','tools/'))})
meta={'baseline':'fixed JSON stage A','baseline_commit':previous['baseline_commit'],'baseline_images':{v:previous['images'][v] for v in ['candidate','candidate-diag']},'runtime_id':previous['runtime_id'],'source_sha256':{f:hashlib.sha256((root/f).read_bytes()).hexdigest() for f in changed},'go':subprocess.check_output(['go','version'],text=True).strip()}
meta['images']={'baseline':previous['images']['candidate'],'baseline-diag':previous['images']['candidate-diag']}
for v in ['candidate','candidate-diag']:
 src=p/(v+'-source');shutil.copytree(old/'candidate-source',src)
 for f in changed:(src/f).parent.mkdir(parents=True,exist_ok=True);shutil.copy2(root/f,src/f)
 if v.endswith('diag'):
  for f in ['cmd/oimobbs/probe_profile.go','internal/textcodec/codec.go','internal/textcodec/probe_input.go','internal/store/durable.go','internal/store/thread_group.go','internal/store/probe_sync.go']:shutil.copy2(old/'candidate-diag-source'/f,src/f)
 ctx=p/(v+'-image');ctx.mkdir();image='oimobbs:posting-json-second-'+v+'-20261025';runtime='oimobbs:compression-memory512-20261025'
 assert subprocess.check_output(['docker','image','inspect',runtime,'--format','{{.Id}}'],text=True).strip()==meta['runtime_id']
 with (p/(v+'-build.log')).open('w') as log:
  subprocess.run(['go','build','-p','2','-trimpath','-ldflags=-s -w','-o',str(ctx/'oimobbs'),'./cmd/oimobbs'],cwd=src,env=dict(os.environ,CGO_ENABLED='0',GOMAXPROCS='2'),stdout=log,stderr=subprocess.STDOUT,check=True)
  (ctx/'Dockerfile').write_text('FROM '+runtime+'\nCOPY oimobbs /usr/local/bin/oimobbs\n')
  subprocess.run(['docker','build','--network=none','-t',image,str(ctx)],stdout=log,stderr=subprocess.STDOUT,check=True)
 meta['images'][v]={'image':image,'id':subprocess.check_output(['docker','image','inspect',image,'--format','{{.Id}}'],text=True).strip()}
for f in ['balanced120-probe.py','balanced120_capacity.py','crash-probe.py']:shutil.copy2(old/f,p/f)
(p/'setup.json').write_text(json.dumps(meta,indent=2));print('IMAGES READY',flush=True)

