"""符号化・検証の第二段階を第一段階と同じ固定仕事量で比較する。"""
import pathlib,json,subprocess,time,sys,os
p=pathlib.Path(__file__).resolve().parent;root=p.parents[1];setup=json.loads((p/'setup.json').read_text());rows=json.loads((p/'trials.json').read_text()) if (p/'trials.json').exists() else []
setup['images']['unprofiled-baseline']=setup['images']['baseline-diag']
setup['images']['unprofiled-candidate']=setup['images']['candidate-diag']
base=['mise','exec','--','python3',str(p/'balanced120-probe.py'),'--memory','4g','--egress-bps','80000000','--waf','--waf-posting-rate','100000','--waf-posting-concurrent','256','--waf-posting-client-rate','1000','--optional-log-stats','--collect-server-log','--posting-capacity-rate','1600','--posting-capacity-seconds','5','--posting-capacity-workers','120','--posting-capacity-threads','16','--posting-capacity-fixed-count']
def run(v,cpu,rep,kind='fixed'):
 name=f'{kind}-{v}-r{rep}-{cpu}cpu';dest=p/(name+'.json')
 if any(r['name']==name for r in rows):return
 assert not dest.exists(),name
 cmd=base+['--image',setup['images'][v]['id'],'--cpus',str(cpu),'--output',str(dest)]
 if kind=='control-idle':cmd[4]=str(p/'idle-probe.py')
 if kind=='mixed':
  cmd.remove('--posting-capacity-fixed-count')
  for flag,value in [('--posting-capacity-rate','160'),('--posting-capacity-seconds','60'),('--egress-bps','8000000000')]:cmd[cmd.index(flag)+1]=value
  cmd+=['--posting-capacity-reads','400','--posting-capacity-subject-every','4','--posting-capacity-restart']
 if v.endswith('diag'):cmd+=['--collect-profiles']
 print('START',name,flush=True);start=time.monotonic()
 with (p/(name+'.log')).open('w') as f:r=subprocess.run(cmd,cwd=root,stdout=f,stderr=subprocess.STDOUT)
 row={'name':name,'version':v,'cpus':cpu,'rep':rep,'kind':kind,'exit_code':r.returncode,'command':cmd,'wall_s':time.monotonic()-start}
 if dest.exists():
  s=json.loads(dest.read_text());d=s['duration_with_drain_seconds'];n=s['summary']['success']
  row.update({'throughput':n/d,'cpu_ms_per_success':s['resources']['cpu_cores_average']*d*1000/max(n,1),'summary':s['summary'],'read_summary':s['read_summary'],'integrity':s['integrity']['ok'],'recovery':s['recovery'],'resources':s['resources'],'memory_peak_bytes':s['memory_peak_bytes']})
 rows.append(row);(p/'trials.json').write_text(json.dumps(rows,indent=2));print('DONE',name,json.dumps({k:row.get(k) for k in ['exit_code','throughput','cpu_ms_per_success','summary']}),flush=True)
 assert r.returncode==0 and row.get('integrity') and not row['resources']['oom_kill_delta'] and row['recovery']['success']==100,name
 if kind!='mixed':assert not row['summary']['errors'] and not row['summary']['skipped'],name
mode=sys.argv[1]
if mode=='fixed':
 # 最後の種別選択フォールバックを最終ソースでrace再確認し、終了後にだけ計時する。
 with (p/'final-schema-race.log').open('w') as f:subprocess.run(['mise','exec','--','go','test','-race','./internal/strictjson','./internal/postcapture','-timeout','600s'],cwd=root,env=dict(os.environ,GOMAXPROCS='4'),stdout=f,stderr=subprocess.STDOUT,check=True)
 for rep in [1,2]:
  for cpu in [1,2,4]:
   for v in (['baseline','candidate'] if (rep+cpu)%2==0 else ['candidate','baseline']):run(v,cpu,rep)
elif mode=='diagnostic':
 for cpu in [2,4]:
  for v in (['baseline-diag','candidate-diag'] if cpu==2 else ['candidate-diag','baseline-diag']):run(v,cpu,1,'diagnostic')
elif mode=='mixed':
 for v in ['baseline','candidate']:run(v,4,1,'mixed')
elif mode=='controls':
 for v in ['candidate','baseline']:run(v,4,1,'control-idle')
 for v in ['unprofiled-candidate','unprofiled-baseline']:run(v,4,1,'control-unprofiled')
elif mode=='extra':
 cpu=int(sys.argv[2]);rep=int(sys.argv[3])
 for v in ['candidate','baseline']:run(v,cpu,rep)
else:raise ValueError(mode)
print('COMPLETE',mode,flush=True)

