"""通常検査後にraceと独立差分fuzzを行い、性能計測とは重ねない。"""
import pathlib,subprocess,os,concurrent.futures,json,time
p=pathlib.Path(__file__).resolve().parent;root=p.parents[1];out={}
def run(name,cmd,env=None):
 start=time.monotonic();print('START',name,flush=True)
 with (p/(name+'.log')).open('w') as f:r=subprocess.run(['mise','exec','--',*cmd],cwd=root,env=dict(os.environ,**(env or {})),stdout=f,stderr=subprocess.STDOUT)
 record={'command':cmd,'env':env or {},'exit_code':r.returncode,'wall_s':time.monotonic()-start};print('DONE',name,r.returncode,flush=True)
 if r.returncode:raise RuntimeError(name+' failed')
 return name,record
name,r=run('full-normal',['go','test','-p','3','./cmd/...','./internal/...','./tools/...','-timeout','900s'],{'GOMAXPROCS':'4'});out[name]=r
(p/'validation-normal.json').write_text(json.dumps(out,indent=2))
def fuzz_group(group,cases):
 records={}
 for pkg,fn,seconds in cases:
  name,r=run('fuzz-'+fn,['go','test','./internal/'+pkg,'-run','^$','-fuzz','^'+fn+'$','-fuzztime',str(seconds)+'s','-parallel','2'],{'GOMAXPROCS':'2'});records[name]=r
 return group,records
strict=[('strictjson','FuzzValidateMatchesToken',60),('strictjson','FuzzCheckedEquivalence',60),('strictjson','FuzzCheckedSchemaSelection',30)]
enc=[('jsonencode','FuzzString',30),('evidence','FuzzGeneratedObservationJSON',30),('postcapture','FuzzGeneratedCaptureJSON',30),('domain','FuzzGeneratedDomainJSON',30),('evidence','FuzzGeneratedOptionalJSON',20),('evidence','FuzzDecodedObservationEquivalence',30)]
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as ex:
 jobs=[ex.submit(run,'core-race',['go','test','-p','1','-race','./internal/jsonencode','./internal/strictjson','./internal/domain','./internal/postinput','./internal/postcapture','./internal/evidence','./internal/store','./internal/app','-timeout','900s'],{'GOMAXPROCS':'4'}),ex.submit(fuzz_group,'strict-fuzz',strict),ex.submit(fuzz_group,'encoder-fuzz',enc)]
 for future in concurrent.futures.as_completed(jobs):
  name,r=future.result();out[name]=r;(p/'validation.json').write_text(json.dumps(out,indent=2))
print('VALIDATION COMPLETE',flush=True)

