"""通常負荷を止めてから、診断のCPU標本と待機・割当を分類する。"""
import pathlib,subprocess,re,json
p=pathlib.Path(__file__).resolve().parent;rows=[]
patterns={'json':r'(encoding/json|oimobbs/internal/strictjson|oimobbs/internal/jsonencode|appendJSON|marshalJournalOperation|internal/(domain|evidence|postcapture)\.Marshal|HTTPObservationJSONBound)','signature':r'ed25519','compression':r'(zstdencode|zstddecode|compress/flate)','journal_encode':r'(prepareBatchFrames|prepareOptionalBatch.func2)'}
for folder in sorted(p.glob('diagnostic-*.json.profiles')):
 for name,pattern in patterns.items():
  r=subprocess.run(['go','tool','pprof','-top','-nodecount=100000','-nodefraction=0','-edgefraction=0','-focus='+pattern,str(folder/'cpu.pprof')],check=True,capture_output=True,text=True)
  (folder/('cpu-share-'+name+'.txt')).write_text(r.stdout+r.stderr)
  m=re.search(r'Showing nodes accounting for ([\d.]+)s, ([\d.]+)% of ([\d.]+)s total',r.stdout)
  rows.append({'trial':folder.name.removesuffix('.json.profiles'),'category':name,'matched_cpu_seconds':float(m[1]) if m else None,'percent':float(m[2]) if m else None,'total_cpu_seconds':float(m[3]) if m else None})
 for name,args in [('cpu',['-top','-cum']),('block',['-top']),('mutex',['-top'])]:
  r=subprocess.run(['go','tool','pprof',*args,'-nodecount=30',str(folder/(name+'.pprof'))],check=True,capture_output=True,text=True);(folder/(name+'-top.txt')).write_text(r.stdout+r.stderr)
(p/'cpu-shares.json').write_text(json.dumps(rows,indent=2));print(json.dumps(rows,indent=2))

