import fs from 'node:fs';
import http from 'node:http';
import path from 'node:path';
import MarkdownIt from 'markdown-it';
import GithubSlugger from 'github-slugger';
import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const {chromium} = require('/tmp/oimo-passkey-browser/node_modules/playwright');
const root = '/home/patatan/OimoBBS';
const files = ['docs/features/resources.md','docs/testing/measurements.md','docs/testing/posting-json-second.md'];
const md = new MarkdownIt({html:true});
const css = fs.readFileSync('/tmp/oimo-docs-preview/node_modules/github-markdown-css/github-markdown.css','utf8');
function render(file) {
  const tokens = md.parse(fs.readFileSync(path.join(root,file),'utf8')), slugger = new GithubSlugger();
  for(let i=0;i<tokens.length;i++) if(tokens[i].type==='heading_open') tokens[i].attrSet('id',slugger.slug(tokens[i+1].content));
  return '<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><style>'+css+'\nbody{margin:0}.markdown-body{box-sizing:border-box;max-width:1012px;margin:auto;padding:32px}@media(max-width:767px){.markdown-body{padding:16px}}</style><article class="markdown-body">'+md.renderer.render(tokens,md.options,{})+'</article></html>';
}
const server = http.createServer((req,res)=>{
  const file = decodeURIComponent(new URL(req.url,'http://localhost').pathname).slice(1);
  if(!file.endsWith('.md') || !fs.existsSync(path.join(root,file)) || !path.resolve(root,file).startsWith(root+'/')) {res.writeHead(404).end();return;}
  res.setHeader('Content-Type','text/html; charset=utf-8');res.end(render(file));
});
await new Promise(r=>server.listen(0,'127.0.0.1',r));
const base='http://127.0.0.1:'+server.address().port;
const browser=await chromium.launch({headless:true,executablePath:'/home/patatan/.cache/ms-playwright/chromium-1187/chrome-linux/chrome'});
let clicks=0, layouts=0, anchors=0;
try {
 for(const width of [390,1280]) {
  const page=await browser.newPage({viewport:{width,height:1000}});
  for(const file of files) {
   await page.goto(base+'/'+file);
   const result=await page.evaluate(()=>({overflow:document.documentElement.scrollWidth>innerWidth,missing:[...document.querySelectorAll('a[href^="#"]')].map(a=>decodeURIComponent(a.hash.slice(1))).filter(id=>!document.getElementById(id)),anchors:document.querySelectorAll('a[href^="#"]').length,tables:document.querySelectorAll('table').length}));
   if(result.overflow || result.missing.length || !result.tables) throw new Error(file+': '+JSON.stringify(result));
   anchors+=result.anchors;layouts++;
   const anchor=page.locator('a[href^="#"]').first();
   if(await anchor.count()) {await anchor.click();if(!new URL(page.url()).hash)throw new Error('No hash after click');clicks++;}
   await page.goto(base+'/'+file);
   await page.screenshot({path:'/home/patatan/OimoBBS/var/posting-json-second-20261025/'+file.replaceAll('/','-')+'-'+width+'.png'});
  }
  await page.goto(base+'/docs/testing/measurements.md');
  await page.getByRole('link',{name:'投稿JSONの符号化・検証の追加改善',exact:true}).click();
  if(!page.url().endsWith('/posting-json-second.md'))throw new Error('Wrong report');
  clicks++;
  await page.close();
 }
 console.log(JSON.stringify({layouts,widths:[390,1280],localAnchorsChecked:anchors,successfulClicks:clicks,screenshots:'/home/patatan/OimoBBS/var/posting-json-second-20261025/'}));
} finally {await browser.close();await new Promise(r=>server.close(r));}
